css:
    body {
      font-family: Arial, sans-serif;
      margin: 20px;
      direction: ltr;
    }

    h1 {
      text-align: center;
      font-size: 24px;
      margin-bottom: 20px;
      /*color: ;*/
    }

    .table-c {
      margin-bottom: 30px;
    }
.table-container {
  display: flex;
  gap: 20px; /* مسافة بين الجدولين */
}
    table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 20px;
      /*background-color: #f9f9f9;*/
    }

    th, td {
      padding: 10px;
      text-align: center;
      border: 1px solid #ddd;
            font-size: 13px;

    }

    th {
      background-color: #ddd;
      font-weight: bold;
    }
    .category-column {
            background-color: #f0f8ff;
            font-weight: bold;
            text-align: left;
    }
    /*tr:nth-child(even) {*/
    /*  background-color: #f2f2f2;*/
    /*}*/

    tr:hover {
      background-color: #ddd;
    }

  .details-section {
  margin-bottom: 20px;
  padding: 15px;
  background-color: #eff3f7;
  border-radius: 8px;
  display: grid;
  grid-template-columns: auto 1fr; /* عمودان: الأول ثابت والثاني مرن */
  gap: 10px 20px; /* مسافة بين العناوين والقيم */
  align-items: center; /* محاذاة القيم أفقياً */
}

.details-section p {
  margin: 0;
  font-size: 13px;
  color: #333;
  display: contents; /* يسمح باستخدام كل عنصر داخلي في الشبكة */
}

.details-section strong {
  font-weight: bold;
}


    .summary-table th {
      background-color: #f2f2f2;
    }
    
    
    .same-type-row {
    border-top: none; /* إزالة الحد العلوي بين الصفوف من نفس النوع */
}
    /* تنسيقات الطباعة */
    @media print {
        body {
            font-size: 12pt !important;
            line-height: 1.5;
            margin: 0;
            padding: 10px;
        }
        
        h1, h2, h3 {
            page-break-after: avoid;
        }
        
        table {
            font-size: 10pt !important;
            page-break-inside: avoid;
        }
        
        th, td {
            padding: 6px 4px !important;
        }
        
        .chart-container {
            width: 300px !important;
            height: 300px !important;
            margin: 10px auto !important;
            page-break-inside: avoid;
        }
        
        canvas {
            width: 100% !important;
            height: 100% !important;
            max-height: 300px !important;
        }
        
        .plan-section {
            page-break-after: auto;
            page-break-inside: avoid;
        }
        
        .details-section {
            page-break-inside: avoid;
        }
        
        /* تحسين عرض الجداول الكبيرة */
        .printable-table {
            transform: scale(0.9);
            transform-origin: 0 0;
            width: 90% !important;
        }
    }
